{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table kerala-ayurveda-wh.maplemonk.KA_US_Shopify_UTM_Parameters as select ShopifyQL.* ,upper(coalesce(UTM_MAPPING.CHANNEL,ShopifyQL.ShopifyQL_Unmapped_Last_Source, UTM_MAPPING_REF.CHANNEL)) as ShopifyQL_MAPPED_CHANNEL ,upper(coalesce(UTM_MAPPING.SOURCE,ShopifyQL.ShopifyQL_Unmapped_Last_Source,UTM_MAPPING_REF.SOURCE)) as ShopifyQL_MAPPED_SOURCE from (select * from ( select A.id ,A.name ,A.createdat ,cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.momentsCount\') as int) Moments_Count ,cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.daysToConversion\') as int) DaysToConvert ,cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.lastVisit.utmParameters.source\') as string) LastVisit_UTM_Source ,cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.lastVisit.utmParameters.medium\') as string) LastVisit_UTM_Medium ,cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.lastVisit.source\') as string) LastVisit_NON_UTM_Source ,cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.lastVisit.utmParameters.campaign\') as string) LastVisit_UTM_Campaign ,cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.firstVisit.utmParameters.source\') as string) FirstVisit_UTM_Source ,cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.firstVisit.utmParameters.medium\') as string) FirstVisit_UTM_Medium ,cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.firstVisit.utmParameters.campaign\') as string) FirstVisit_UTM_Campaign ,replace(JSON_EXTRACT_SCALAR(b,\'$.id\') ,\'gid://shopify/CustomerVisit/\',\'\') Moment_ID ,JSON_EXTRACT_SCALAR(b,\'$.utmParameters.source\') Last_Moment_UTM_Source ,JSON_EXTRACT_SCALAR(b,\'$.utmParameters.medium\') Last_Moment_UTM_Medium ,case when cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.momentsCount\') as int) >1 then cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.lastVisit.utmParameters.source\') as string) else cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.firstVisit.utmParameters.source\') as string) end CJSummary_utm_source ,referrerdisplaytext Referrer_Name ,customerjourneysummary ,customerjourney ,coalesce(JSON_EXTRACT_SCALAR(b,\'$.utmParameters.source\') ,cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.lastVisit.utmParameters.source\') as string) ,cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.lastVisit.source\') as string) ) ShopifyQL_Unmapped_Last_Source ,coalesce(JSON_EXTRACT_SCALAR(b,\'$.utmParameters.medium\') ,cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.lastVisit.utmParameters.medium\') as string) ) ShopifyQL_Unmapped_Last_Medium ,rank() over (partition by A.name order by replace(JSON_EXTRACT_SCALAR(b,\'$.id\') ,\'gid://shopify/CustomerVisit/\',\'\') desc) rw from maplemonk.ka_SHOPIFY_us_utm_parameters A left join unnest(JSON_EXTRACT_ARRAY(JSON_EXTRACT(customerjourney, \'$.moments\'))) b ) where rw=1 ) ShopifyQL left join (select * from (select * , row_number() over (partition by lower(concat(ifnull(utm_source,\'\'),ifnull(utm_medium,\'\'))) order by 1) rw from kerala-ayurveda-wh.maplemonk.KA_GS_UTM_MAPPING) where rw=1 and lower(concat(ifnull(utm_source,\'\'),ifnull(utm_medium,\'\'))) is not null ) UTM_MAPPING on lower(concat(ifnull(ShopifyQL.ShopifyQL_Unmapped_Last_Source,\'\'),ifnull(ShopifyQL_Unmapped_Last_Medium,\'\'))) = lower(concat(ifnull(UTM_MAPPING.utm_source,\'\'),ifnull(UTM_MAPPING.utm_medium,\'\'))) left join (select * from (select * , row_number() over (partition by lower(utm_source) order by 1) rw from kerala-ayurveda-wh.maplemonk.KA_GS_utm_mapping) where rw=1 and UTM_Source is not null ) UTM_MAPPING_REF on lower(ShopifyQL.referrer_name) = lower(UTM_MAPPING_REF.utm_source) ; create or replace table kerala-ayurveda-wh.maplemonk.KA_US_CHECKOUT_SOURCE as With CHECKOUT as ( WITH utm_source_cte AS ( SELECT S.id, UPPER(JSON_EXTRACT_SCALAR(A,\'$.value\') ) AS utm_source FROM kerala-ayurveda-wh.maplemonk.KA_Shopify_US_ORDERS S left join UNNEST(S.note_attributes) AS A WHERE (LOWER(ARRAY_TO_STRING(note_attributes,\',\')) LIKE \'%gokwik%\' OR LOWER(ARRAY_TO_STRING(note_attributes,\',\')) LIKE \'%shopflo%\' OR LOWER(S.tags) LIKE \'%gokwik%\' OR LOWER(S.tags) LIKE \'%shopflo%\') AND LOWER(JSON_EXTRACT_SCALAR(A,\'$.name\')) = \'utm_source\' ), utm_medium_cte AS ( SELECT S.id, UPPER(JSON_EXTRACT_SCALAR(A,\'$.value\') ) AS utm_medium FROM kerala-ayurveda-wh.maplemonk.KA_Shopify_US_ORDERS S left join UNNEST(S.note_attributes) AS A WHERE (LOWER(ARRAY_TO_STRING(note_attributes,\',\')) LIKE \'%gokwik%\' OR LOWER(ARRAY_TO_STRING(note_attributes,\',\')) LIKE \'%shopflo%\' OR LOWER(S.tags) LIKE \'%gokwik%\' OR LOWER(S.tags) LIKE \'%shopflo%\') AND LOWER(JSON_EXTRACT_SCALAR(A,\'$.name\')) = \'utm_medium\' ), utm_campaign_cte AS ( SELECT S.id, UPPER(JSON_EXTRACT_SCALAR(A,\'$.value\') ) AS utm_campaign FROM kerala-ayurveda-wh.maplemonk.KA_Shopify_US_ORDERS S left join UNNEST(S.note_attributes) AS A WHERE (LOWER(ARRAY_TO_STRING(note_attributes,\',\')) LIKE \'%gokwik%\' OR LOWER(ARRAY_TO_STRING(note_attributes,\',\')) LIKE \'%shopflo%\' OR LOWER(S.tags) LIKE \'%gokwik%\' OR LOWER(S.tags) LIKE \'%shopflo%\') AND LOWER(JSON_EXTRACT_SCALAR(A,\'$.name\')) = \'utm_campaign\' ), utm_content_cte AS ( SELECT S.id, UPPER(JSON_EXTRACT_SCALAR(A,\'$.value\') ) AS utm_content FROM kerala-ayurveda-wh.maplemonk.KA_Shopify_US_ORDERS S left join UNNEST(S.note_attributes) AS A WHERE (LOWER(ARRAY_TO_STRING(note_attributes,\',\')) LIKE \'%gokwik%\' OR LOWER(ARRAY_TO_STRING(note_attributes,\',\')) LIKE \'%shopflo%\' OR LOWER(S.tags) LIKE \'%gokwik%\' OR LOWER(S.tags) LIKE \'%shopflo%\') AND LOWER(JSON_EXTRACT_SCALAR(A,\'$.name\')) = \'utm_content\' ) SELECT S.id, S.tags, source_cte.utm_source AS CHECKOUT_UTM_SOURCE, medium_cte.utm_medium AS CHECKOUT_UTM_MEDIUM, campaign_cte.utm_campaign AS CHECKOUT_UTM_CAMPAIGN, content_cte.utm_content AS CHECKOUT_UTM_CONTENT FROM kerala-ayurveda-wh.maplemonk.KA_Shopify_US_ORDERS S LEFT JOIN utm_source_cte source_cte ON S.id = source_cte.id LEFT JOIN utm_medium_cte medium_cte ON S.id = medium_cte.id LEFT JOIN utm_campaign_cte campaign_cte ON S.id = campaign_cte.id LEFT JOIN utm_content_cte content_cte ON S.id = content_cte.id where (LOWER(ARRAY_TO_STRING(note_attributes,\',\')) LIKE \'%gokwik%\' OR LOWER(ARRAY_TO_STRING(note_attributes,\',\')) LIKE \'%shopflo%\' OR LOWER(S.tags) LIKE \'%gokwik%\' OR LOWER(S.tags) LIKE \'%shopflo%\') ) Select CHECKOUT.* ,coalesce(Upper(UTM_MAPPING.CHANNEL), upper(CHECKOUT_UTM_SOURCE),\'DIRECT\') as CHECKOUT_MAPPED_CHANNEL ,coalesce(Upper(UTM_MAPPING.CHANNEL), upper(CHECKOUT_UTM_SOURCE),\'DIRECT\') as CHECKOUT_MAPPED_SOURCE from CHECKOUT left join (select * from (select * , row_number() over (partition by lower(concat(ifnull(utm_source,\'\'),ifnull(utm_medium,\'\'))) order by 1) rw from kerala-ayurveda-wh.maplemonk.KA_GS_UTM_MAPPING) where rw=1 and lower(concat(ifnull(utm_source,\'\'),ifnull(utm_medium,\'\'))) is not null ) UTM_MAPPING on lower(concat(ifnull(CHECKOUT.CHECKOUT_UTM_SOURCE,\'\'),ifnull(CHECKOUT_UTM_MEDIUM,\'\'))) = lower(concat(ifnull(UTM_MAPPING.utm_source,\'\'),ifnull(UTM_MAPPING.utm_medium,\'\'))) ; CREATE OR REPLACE TABLE kerala-ayurveda-wh.maplemonk.Shopify_us_All_customers AS select *,\'WEBSITE US\' AS Shop_Name from kerala-ayurveda-wh.maplemonk.KA_Shopify_us_CUSTOMERS ; create or replace table kerala-ayurveda-wh.maplemonk.Shopify_US_All_orders as select AO.* ,UPPER(ShopifyQL.shopifyql_mapped_channel) shopifyql_mapped_channel ,UPPER(ShopifyQL.shopifyql_mapped_source) shopifyql_mapped_source ,UPPER(ShopifyQL.FIRSTVISIT_UTM_SOURCE) Shopifyql_FIRSTVISIT_UTM_SOURCE ,UPPER(ShopifyQL.FirstVisit_UTM_Campaign) Shopifyql_FIRSTVISIT_UTM_CAMPAIGN ,upper(ShopifyQL.LastVisit_UTM_Campaign) Shopifyql_LAST_VISIT_UTM_CAMPAIGN ,UPPER(ShopifyQL.LAST_MOMENT_UTM_SOURCE) Shopifyql_LAST_MOMENT_UTM_SOURCE ,UPPER(ShopifyQL.LastVisit_NON_UTM_Source) Shopifyql_LAST_VISIT_NON_UTM_SOURCE ,UPPER(ShopifyQL.LAST_MOMENT_UTM_MEDIUM) Shopifyql_LAST_MOMENT_UTM_MEDIUM ,UPPER(ShopifyQL.FIRSTVISIT_UTM_MEDIUM) Shopifyql_FIRSTVISIT_UTM_MEDIUM ,safe_divide(ShopifyQL.MOMENTS_COUNT,count(1) over (partition by AO.name order by 1)) MOMENTS_COUNT ,safe_divide(ShopifyQL.DAYSTOCONVERT,count(1) over (partition by AO.name order by 1)) DAYSTOCONVERT ,UPPER(CHECKOUT.CHECKOUT_UTM_SOURCE) CHECKOUT_UTM_SOURCE ,UPPER(CHECKOUT.CHECKOUT_UTM_MEDIUM) CHECKOUT_UTM_MEDIUM ,UPPER(CHECKOUT.CHECKOUT_UTM_CONTENT) CHECKOUT_UTM_CONTENT ,UPPER(CHECKOUT.CHECKOUT_MAPPED_CHANNEL) CHECKOUT_MAPPED_CHANNEL ,UPPER(CHECKOUT.CHECKOUT_MAPPED_SOURCE) CHECKOUT_MAPPED_SOURCE ,UPPER(Referrer_Name) Referrer_Name ,UPPER(CHECKOUT.CHECKOUT_UTM_CAMPAIGN) CHECKOUT_UTM_CAMPAIGN ,UPPER(coalesce(LastVisit_UTM_Campaign,CHECKOUT_UTM_CAMPAIGN)) FINAL_UTM_CAMPAIGN ,Upper(coalesce(shopifyql_mapped_source,CHECKOUT_MAPPED_SOURCE,ShopifyQL.ShopifyQL_Unmapped_Last_Source,\'Direct\')) FINAL_UTM_SOURCE ,Upper(coalesce(shopifyql_mapped_channel,CHECKOUT_MAPPED_CHANNEL,ShopifyQL.ShopifyQL_Unmapped_Last_Source,\'Direct\')) FINAL_UTM_CHANNEL ,coalesce(JSON_EXTRACT_SCALAR(AO.SHIPPING_ADDRESS,\'$.zip\'),JSON_EXTRACT_SCALAR(AO.billing_address,\'$.zip\')) as pincode from (select *,case when lower(source_name) like \'pos\' then \'SHOPIFY POS\' else \'WEBSITE INDIA\' end AS Shop_Name from kerala-ayurveda-wh.maplemonk.KA_Shopify_US_ORDERS ) AO left join kerala-ayurveda-wh.maplemonk.KA_US_Shopify_UTM_Parameters ShopifyQL on AO.name = ShopifyQL.name left join kerala-ayurveda-wh.maplemonk.KA_US_CHECKOUT_SOURCE CHECKOUT on AO.ID = CHECKOUT.ID ; ALTER TABLE kerala-ayurveda-wh.maplemonk.Shopify_us_All_orders RENAME COLUMN _airbyte_KA_Shopify_US_ORDERS_hashid to _AIRBYTE_ORDERS_HASHID; CREATE OR REPLACE TABLE kerala-ayurveda-wh.maplemonk.Shopify_us_All_products AS select *,\'WEBSITE US\' AS Shop_Name from kerala-ayurveda-wh.maplemonk.KA_Shopify_us_PRODUCTS; ALTER TABLE kerala-ayurveda-wh.maplemonk.Shopify_us_All_products RENAME COLUMN _airbyte_KA_SHOPIFY_us_products_hashid to _AIRBYTE_PRODUCTS_HASHID; CREATE OR REPLACE TABLE kerala-ayurveda-wh.maplemonk.Shopify_us_All_products_variants AS select *,\'WEBSITE US\' AS Shop_Name from kerala-ayurveda-wh.maplemonk.KA_Shopify_us_PRODUCTS_VARIANTS ; ALTER TABLE kerala-ayurveda-wh.maplemonk.SHOPIFY_us_ALL_PRODUCTS_VARIANTS RENAME COLUMN _airbyte_KA_SHOPIFY_us_products_hashid to _AIRBYTE_PRODUCTS_HASHID; CREATE OR REPLACE TABLE kerala-ayurveda-wh.maplemonk.Shopify_us_All_customers_addresses AS select *,\'WEBSITE US\' AS Shop_Name from kerala-ayurveda-wh.maplemonk.KA_Shopify_us_CUSTOMERS_ADDRESSES ; CREATE OR REPLACE TABLE kerala-ayurveda-wh.maplemonk.Shopify_us_All_orders_items_discount AS select dis_amount.order_id, LINE_ITEM_ID, DISCOUNT, discount_codes from ( SELECT order_id, LINE_ITEM_ID, SUM(cast(JSON_EXTRACT_SCALAR(c,\'$.amount\')as FLOAT64)) AS DISCOUNT from ( SELECT A.id AS order_id, JSON_EXTRACT_SCALAR(B,\'$.id\') AS LINE_ITEM_ID, JSON_EXTRACT_ARRAY(B,\'$.discount_allocations\') AS discount_allocations FROM kerala-ayurveda-wh.maplemonk.Shopify_us_All_orders A left join unnest(A.LINE_ITEMS)B) left join unnest(discount_allocations) C GROUP BY ORDER_ID,LINE_ITEM_ID )dis_amount LEFT JOIN ( select * from ( SELECT A.id AS order_id, JSON_EXTRACT_SCALAR(B, \"$.code\") AS discount_codes FROM `MAPLEMONK.Shopify_us_All_orders` AS A left join UNNEST(A.discount_codes) AS B ) qualify row_number() over(partition by order_id order by 1) = 1 ) AS dis_codes ON dis_amount.order_id = dis_codes.order_id; CREATE OR REPLACE TABLE kerala-ayurveda-wh.maplemonk.Shopify_us_All_orders_items_tax AS SELECT order_id, LINE_ITEM_ID, SUM(cast(JSON_EXTRACT_SCALAR(c,\'$.price\')as FLOAT64)) AS tax, AVG(cast(JSON_EXTRACT_SCALAR(c,\'$.rate\')as FLOAT64)) AS Tax_Rate FROM( SELECT A.id AS order_id, JSON_EXTRACT_SCALAR(B,\'$.id\') AS LINE_ITEM_ID, JSON_EXTRACT_ARRAY(B,\'$.tax_lines\') AS tax_lines FROM kerala-ayurveda-wh.maplemonk.Shopify_us_All_orders A left join unnest(A.LINE_ITEMS)B )x left join unnest(x.tax_lines) C group by order_id,LINE_ITEM_ID; CREATE OR REPLACE TABLE kerala-ayurveda-wh.maplemonk.Shopify_us_All_Refunds AS WITH refund_line_items AS ( SELECT JSON_EXTRACT_SCALAR(refunds,\'$.order_id\') as order_id, JSON_EXTRACT_SCALAR(line_items,\'$.line_item_id\') as LINE_ITEM_ID, JSON_EXTRACT_SCALAR(line_items,\'$.created_at\') as refund_date, sum(cast(JSON_EXTRACT_SCALAR(line_items,\'$.quantity\') as float64)) as refund_quantity, sum(cast(JSON_EXTRACT_SCALAR(line_items,\'$.subtotal\') as float64 )) as refund_subtotal, FROM kerala-ayurveda-wh.maplemonk.Shopify_us_All_orders A left join unnest(A.refunds) refunds left join unnest(JSON_EXTRACT_ARRAY(JSON_EXTRACT(refunds, \'$.refund_line_items\'))) line_items where JSON_EXTRACT_SCALAR(refunds,\'$.order_id\') is not null group by 1,2,3 ), order_adjustments AS ( SELECT JSON_EXTRACT_SCALAR(order_adj,\'$.order_id\') AS order_id, JSON_EXTRACT_SCALAR(refunds, \'$.created_at\') AS adjustment_date, sum(cast(JSON_EXTRACT_SCALAR(order_adj,\'$.amount\') as float64 )) adjustment FROM kerala-ayurveda-wh.maplemonk.Shopify_us_All_orders A left join unnest(A.refunds) refunds left join unnest(JSON_EXTRACT_ARRAY(JSON_EXTRACT(refunds, \'$.order_adjustments\'))) order_adj group by 1,2 ), adj_refund as ( Select distinct order_id, line_item_id, date from ( select coalesce(rl.order_id,oa.order_id) order_id, rl.line_item_id, case when rl.refund_date = oa.adjustment_date then rl.refund_date else coalesce(oa.adjustment_date, rl.refund_date) end as date from refund_line_items rl full outer join order_adjustments oa on rl.order_id = oa.order_id ) ), refund_summary as ( select ar.order_id, ar.line_item_id, ar.date, ifnull(rl.refund_quantity,0) refund_quantity, ifnull(rl.refund_subtotal,0) refund_subtotal, ifnull(safe_divide(oa.adjustment,count(1) over (partition by ar.order_id, ar.date)),0) as Adjustment_amount, (ifnull(rl.refund_subtotal,0) - ifnull(ifnull(safe_divide(oa.adjustment,count(1) over (partition by ar.order_id, ar.date)),0),0)) Total_Refund from adj_refund ar left join refund_line_items rl on ar.order_id = rl.order_id and ar.date = rl.refund_date and ar.line_item_id = rl.line_item_id left join order_adjustments oa on ar.order_id = oa.order_id and ar.date = oa.adjustment_date ), aggregate_summary AS ( SELECT order_id, line_item_id, date, sum(refund_quantity) AS Refund_Quantity, sum(Total_Refund) AS Refund_Amount, sum(Adjustment_amount) AS Adjustment_Amount, sum(refund_subtotal) AS Refund_Before_Adjustment FROM refund_summary GROUP BY order_id, line_item_id, date ) SELECT asum.order_id, asum.line_item_id, SUM(asum.Refund_Quantity) AS Quantity, SUM(asum.Refund_Amount) AS Amount, SUM(asum.Adjustment_Amount) AS Adjustment_Amount, SUM(asum.Refund_Before_Adjustment) AS Refund_Before_Adjustment, ARRAY_AGG( STRUCT( date AS Refund_Date, CAST(asum.Refund_Quantity AS FLOAT64) AS Refund_Quantity, CAST(asum.Adjustment_Amount AS FLOAT64) AS Adjustment_Amount, CAST(asum.Refund_Amount AS FLOAT64) AS Refund_Amount ) ) AS Refund_Details FROM aggregate_summary asum GROUP BY asum.order_id, asum.line_item_id; CREATE OR REPLACE TABLE kerala-ayurveda-wh.maplemonk.Shopify_us_All_orders_fulfillment AS WITH UnnestedOrders AS ( SELECT JSON_EXTRACT_SCALAR(fulfillment, \'$.order_id\') AS order_id, JSON_EXTRACT_ARRAY(fulfillment, \'$.line_items\') AS line_item, JSON_EXTRACT_SCALAR(fulfillment, \'$.tracking_number\') AS AWB, JSON_EXTRACT_SCALAR(fulfillment, \'$.tracking_company\') AS Courier, JSON_EXTRACT_SCALAR(fulfillment, \'$.shipment_status\') AS SHIPPING_STATUS, JSON_EXTRACT_SCALAR(fulfillment, \'$.updated_at\') AS shipping_status_update_date, JSON_EXTRACT_SCALAR(fulfillment, \'$.tracking_url\') AS tracking_url, JSON_EXTRACT_SCALAR(fulfillment, \'$.created_at\') AS Shipping_created_at FROM `kerala-ayurveda-wh.maplemonk.Shopify_us_All_orders`, UNNEST(fulfillments) AS fulfillment where lower(JSON_EXTRACT_SCALAR(fulfillment, \'$.status\')) not like \'%cancel%\' ) select * from ( select us.*,JSON_EXTRACT_SCALAR(li, \'$.id\') AS Line_Item_ID ,row_number() over(partition by order_id ,JSON_EXTRACT_SCALAR(li, \'$.id\') order by cast(shipping_status_update_date as timestamp) desc )rw from UnnestedOrders us left join unnest(line_item) li ) where rw = 1; create or replace table kerala-ayurveda-wh.maplemonk.Shopify_us_All_orders_shipping_lines_discount as SELECT id as Order_ID, sum(cast(JSON_EXTRACT_SCALAR(da,\'$.amount\') as float64)) AS total_shipping_discount, FROM kerala-ayurveda-wh.maplemonk.Shopify_us_All_orders left join unnest(shipping_lines)sl left join unnest(JSON_EXTRACT_ARRAY(JSON_EXTRACT(sl, \'$.discount_allocations\'))) da group by 1 ; CREATE OR REPLACE TABLE kerala-ayurveda-wh.maplemonk.Shopify_US_All_orders_items AS WITH mapping AS ( SELECT CAST(name AS STRING) AS name, actual_date FROM kerala-ayurveda-wh.maplemonk.KA_US_BC_Orders_Mapping ), orders_prepped AS ( SELECT o.*, m.actual_date, COALESCE( m.actual_date, IF( REGEXP_CONTAINS(LOWER(o.tags), r\'\bmigrated_orders\b\'), DATE(TIMESTAMP(o.processed_at), \'America/Los_Angeles\'), DATE(TIMESTAMP(o.created_at) , \'America/Los_Angeles\') ) ) AS ORDER_TIMESTAMP FROM kerala-ayurveda-wh.maplemonk.Shopify_US_All_orders AS o LEFT JOIN mapping AS m ON o.name = m.name ), CTE AS ( SELECT op.SHOP_NAME, CAST(op.ID AS STRING) AS ORDER_ID, op.NAME AS ORDER_NAME, op.CUSTOMER, JSON_EXTRACT_SCALAR(op.CUSTOMER, \'$.default_address.name\') AS CUSTOMER_NAME, op.PHONE, op.EMAIL, op.TAGS, JSON_EXTRACT_SCALAR(item, \'$.id\') AS LINE_ITEM_ID, JSON_EXTRACT_SCALAR(item, \'$.sku\') AS SKU, JSON_EXTRACT_SCALAR(item, \'$.product_id\')AS PRODUCT_ID, JSON_EXTRACT_SCALAR(item, \'$.title\') AS PRODUCT_NAME, op.CURRENCY, CASE WHEN op.CANCELLED_AT IS NOT NULL AND LOWER(op.fulfillment_status) != \'fulfilled\' THEN \'CANCELLED\' ELSE \'SHOPIFY_PROCESSED\' END AS ORDER_STATUS, op.ORDER_TIMESTAMP AS ORDER_TIMESTAMP, CAST(JSON_EXTRACT_SCALAR(item,\'$.price\') AS FLOAT64) * CAST(JSON_EXTRACT_SCALAR(item,\'$.quantity\') AS FLOAT64) AS LINE_ITEM_SALES, (CAST(JSON_EXTRACT_SCALAR(op.TOTAL_SHIPPING_PRICE_SET,\'$.presentment_money.amount\') AS FLOAT64) / COUNT(op.ID) OVER (PARTITION BY op.ID)) AS SHIPPING_PRICE, CAST(JSON_EXTRACT_SCALAR(item,\'$.price\') AS FLOAT64) / (1 + CAST(JSON_EXTRACT_SCALAR(item,\'$.tax_lines.rate\') AS FLOAT64)) AS PRICE_BEFORE_TAX, CAST(JSON_EXTRACT_SCALAR(item,\'$.quantity\') AS INT64) AS QUANTITY, op.MOMENTS_COUNT, op.DAYSTOCONVERT, op.SHOPIFYQL_LAST_VISIT_UTM_CAMPAIGN, op.SHOPIFYQL_FIRSTVISIT_UTM_CAMPAIGN, op.SHOPIFYQL_FIRSTVISIT_UTM_SOURCE, op.SHOPIFYQL_MAPPED_SOURCE, op.SHOPIFYQL_MAPPED_CHANNEL, op.SHOPIFYQL_LAST_MOMENT_UTM_SOURCE, op.SHOPIFYQL_LAST_VISIT_NON_UTM_SOURCE, op.SHOPIFYQL_LAST_MOMENT_UTM_MEDIUM, op.SHOPIFYQL_FIRSTVISIT_UTM_MEDIUM, op.CHECKOUT_UTM_SOURCE, op.CHECKOUT_UTM_MEDIUM, op.CHECKOUT_UTM_CAMPAIGN, op.CHECKOUT_UTM_CONTENT, op.FINAL_UTM_CAMPAIGN, op.FINAL_UTM_CHANNEL, op.FINAL_UTM_SOURCE, op.REFERRER_NAME, op.CHECKOUT_MAPPED_SOURCE, op.CHECKOUT_MAPPED_CHANNEL, op.PAYMENT_GATEWAY_NAMES AS GATEWAY, op.SHIPPING_ADDRESS, op.PINCODE, op.source_name, op.location_id, op.source_identifier, op.Device_ID, UPPER(op.fulfillment_status) AS fulfillment_status, UPPER(op.financial_status) AS financial_status, CASE WHEN LOWER(ARRAY_TO_STRING(op.PAYMENT_GATEWAY_NAMES,\',\')) LIKE ANY (\'%cod%\',\'%cash%\') THEN \'COD\' ELSE \'PREPAID\' END AS payment_mode FROM orders_prepped AS op LEFT JOIN UNNEST(op.LINE_ITEMS) AS item ) SELECT CTE.*, IFNULL(t.TAX_RATE, 0) AS TAX_RATE, IFNULL(d.DISCOUNT, 0) AS DISCOUNT, d.discount_codes, CTE.LINE_ITEM_SALES AS GROSS_SALES_AFTER_TAX, CTE.LINE_ITEM_SALES / (1 + IFNULL(t.TAX_RATE, 0)) AS GROSS_SALES_BEFORE_TAX, CASE WHEN IFNULL(t.TAX, 0) = 0 THEN IFNULL(d.DISCOUNT, 0) ELSE IFNULL(d.DISCOUNT, 0) / (1 + IFNULL(t.TAX_RATE, 0)) END AS DISCOUNT_BEFORE_TAX, CASE WHEN IFNULL(t.TAX, 0) = 0 THEN CTE.LINE_ITEM_SALES - IFNULL(d.DISCOUNT, 0) ELSE CTE.LINE_ITEM_SALES / (1 + IFNULL(t.TAX_RATE, 0)) - IFNULL(d.DISCOUNT, 0) / (1 + IFNULL(t.TAX_RATE, 0)) END AS NET_SALES_BEFORE_TAX, IFNULL(t.TAX, 0) AS TAX, CASE WHEN IFNULL(t.TAX, 0) = 0 THEN CTE.LINE_ITEM_SALES - IFNULL(d.DISCOUNT, 0) - SAFE_DIVIDE(IFNULL(sd.TOTAL_SHIPPING_DISCOUNT, 0), COUNT(1) OVER (PARTITION BY CTE.ORDER_ID)) + IFNULL(t.TAX, 0) + CTE.SHIPPING_PRICE ELSE CTE.LINE_ITEM_SALES / (1 + IFNULL(t.TAX_RATE, 0)) - IFNULL(d.DISCOUNT, 0) / (1 + IFNULL(t.TAX_RATE, 0)) - SAFE_DIVIDE(IFNULL(sd.TOTAL_SHIPPING_DISCOUNT, 0), COUNT(1) OVER (PARTITION BY CTE.ORDER_ID)) + IFNULL(t.TAX, 0) + CTE.SHIPPING_PRICE END AS TOTAL_SALES, CASE WHEN r.QUANTITY IS NOT NULL THEN 1 ELSE 0 END AS IS_REFUND, r.REFUND_DETAILS, r.QUANTITY AS REFUND_QUANTITY, r.AMOUNT AS REFUND_VALUE, f.AWB, f.COURIER, f.SHIPPING_STATUS, f.SHIPPING_STATUS_UPDATE_DATE, f.TRACKING_URL, f.SHIPPING_CREATED_AT, SAFE_DIVIDE(IFNULL(sd.TOTAL_SHIPPING_DISCOUNT, 0), COUNT(1) OVER (PARTITION BY CTE.ORDER_ID)) AS TOTAL_SHIPPING_DISCOUNT FROM CTE LEFT JOIN kerala-ayurveda-wh.maplemonk.Shopify_US_All_orders_items_tax AS t ON CTE.ORDER_ID = CAST(t.ORDER_ID AS STRING) AND CTE.LINE_ITEM_ID = CAST(t.LINE_ITEM_ID AS STRING) LEFT JOIN kerala-ayurveda-wh.maplemonk.Shopify_US_All_orders_items_discount AS d ON CTE.ORDER_ID = CAST(d.ORDER_ID AS STRING) AND CTE.LINE_ITEM_ID = CAST(d.LINE_ITEM_ID AS STRING) LEFT JOIN kerala-ayurveda-wh.maplemonk.Shopify_US_All_Refunds AS r ON CTE.ORDER_ID = CAST(r.ORDER_ID AS STRING) AND CTE.LINE_ITEM_ID = CAST(r.LINE_ITEM_ID AS STRING) LEFT JOIN kerala-ayurveda-wh.maplemonk.Shopify_US_All_orders_fulfillment AS f ON CTE.ORDER_ID = CAST(f.ORDER_ID AS STRING) AND CTE.LINE_ITEM_ID = CAST(f.LINE_ITEM_ID AS STRING) LEFT JOIN kerala-ayurveda-wh.maplemonk.Shopify_US_All_orders_shipping_lines_discount AS sd ON CTE.ORDER_ID = CAST(sd.ORDER_ID AS STRING) ; CREATE OR REPLACE TABLE kerala-ayurveda-wh.maplemonk.KA_Shopify_US_FACT_ITEMS_INTERMEDIATE AS SELECT O.SHOP_NAME, COALESCE(O.SHOP_NAME,\'WEBSITE US\') AS marketplace, O.ORDER_ID, O.ORDER_NAME, JSON_EXTRACT_SCALAR(O.CUSTOMER, \'$.id\') AS customer_id, O.CUSTOMER_NAME, O.EMAIL, O.PHONE, O.Tags, O.LINE_ITEM_ID, O.SKU, O.PRODUCT_ID, O.CURRENCY, O.IS_REFUND, UPPER(JSON_EXTRACT_SCALAR(O.shipping_address, \'$.city\')) AS shipping_city, UPPER(JSON_EXTRACT_SCALAR(O.shipping_address, \'$.province\')) AS shipping_State, CASE WHEN CD.city IS NULL OR CD.city = \'\' THEN \'NA\' ELSE UPPER(CD.city) END AS city, CASE WHEN CD.province IS NULL OR CD.province = \'\' THEN \'NA\' ELSE UPPER(CD.province) END AS state, CASE WHEN P.title = \'\' THEN \'NA\' ELSE UPPER(P.title) END AS product_name, CASE WHEN P.product_type = \'\' THEN \'NA\' ELSE UPPER(P.product_type) END AS category, UPPER(Coalesce(case when upper(COALESCE(O.SHOP_NAME,\'WEBSITE US\')) =\'SHOPIFY POS\' and O.IS_REFUND = 1 then \'Cancelled\' end,O.order_status)) AS order_status, O.order_timestamp, O.LINE_ITEM_SALES, O.QUANTITY, O.Refund_Quantity, O.Refund_Value, O.TAX, O.TAX_RATE, O.DISCOUNT, O.discount_codes, O.DISCOUNT_BEFORE_TAX, O.GROSS_SALES_AFTER_TAX, O.GROSS_SALES_BEFORE_TAX, O.NET_SALES_BEFORE_TAX, (IFNULL(O.SHIPPING_PRICE, 0) - IFNULL(O.TOTAL_SHIPPING_DISCOUNT, 0)) AS SHIPPING_PRICE, IFNULL(O.TOTAL_SALES, 0) AS TOTAL_SALES, O.MOMENTS_COUNT, O.DAYSTOCONVERT, O.SHOPIFYQL_FIRSTVISIT_UTM_SOURCE, O.SHOPIFYQL_MAPPED_SOURCE, O.SHOPIFYQL_MAPPED_CHANNEL, O.SHOPIFYQL_LAST_MOMENT_UTM_SOURCE, O.Shopifyql_LAST_VISIT_NON_UTM_SOURCE, O.Shopifyql_FIRSTVISIT_UTM_MEDIUM, O.Shopifyql_LAST_MOMENT_UTM_MEDIUM, case when O.SHOP_NAME like \'%POS%\' then \'SHOPIFY POS\' ELSE O.FINAL_UTM_CHANNEL end FINAL_UTM_CHANNEL, O.FINAL_UTM_CAMPAIGN, O.FINAL_UTM_SOURCE, O.Referrer_Name, O.CHECKOUT_MAPPED_SOURCE, O.CHECKOUT_MAPPED_CHANNEL, O.REFUND_DETAILS, O.AWB, UPPER(O.Courier) AS Courier, UPPER(O.Shipping_status) AS SHIPPING_STATUS, O.shipping_status_update_date, O.tracking_url, O.Shipping_created_at, O.GATEWAY, O.payment_mode, O.pincode, O.source_name, O.Location_ID, O.source_identifier, O.Device_ID, O.fulfillment_status, O.financial_status, FROM kerala-ayurveda-wh.maplemonk.Shopify_US_All_orders_items O LEFT JOIN kerala-ayurveda-wh.maplemonk.Shopify_US_All_products P ON cast(O.PRODUCT_ID as string) = cast(P.id as string) LEFT JOIN (SELECT customer_id, city, province, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY id DESC) AS rowid FROM kerala-ayurveda-wh.maplemonk.Shopify_US_All_customers_addresses) AS CD ON JSON_EXTRACT_SCALAR(O.CUSTOMER, \'$.id\') = CAST(CD.customer_id AS STRING) AND cast(CD.rowid as int) = 1; CREATE OR REPLACE TABLE kerala-ayurveda-wh.maplemonk.KA_Shopify_US_FACT_ITEMS_TEMP_Category as select fi.* ,coalesce(p.skucode,fi.SKU) AS SKU_CODE ,p.commonsku ,Upper(coalesce(p.name,fi.product_name)) as PRODUCT_NAME_Final ,coalesce(Upper(p.CATEGORY),upper(fi.category)) AS Product_Category ,Upper(p.sub_category) as Product_Sub_Category from kerala-ayurveda-wh.maplemonk.KA_Shopify_US_FACT_ITEMS_INTERMEDIATE fi left join (select MARKETPLACE_SKU skucode, name, category, category_code sub_category, category_code, MRP, commonsku, TAX_RATE from (select * from maplemonk.final_sku_master where lower(data_source) like \'%shopify%\') qualify row_number() over (partition by lower(ifnull(trim(MARKETPLACE_SKU),\'\')) order by lower(ifnull(trim(COMMONSKU),\'\')) desc) = 1 ) p on lower(replace(fi.sku,\' \',\'\')) = lower(replace(p.skucode,\' \',\'\')) ; CREATE OR REPLACE TABLE kerala-ayurveda-wh.maplemonk.KA_Shopify_US_FACT_ITEMS_INTERMEDIATE AS SELECT * FROM kerala-ayurveda-wh.maplemonk.KA_Shopify_US_FACT_ITEMS_TEMP_Category; drop table `kerala-ayurveda-wh.maplemonk.KA_US_Shopify_FACT_ITEMS`; CREATE OR REPLACE TABLE `kerala-ayurveda-wh.maplemonk.KA_US_Shopify_FACT_ITEMS` AS SELECT COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS Shopify_customer_id_final, MIN(CAST(ORDER_TIMESTAMP AS DATE)) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS shopify_acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN CAST(ORDER_TIMESTAMP AS DATE) END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS shopify_first_complete_order_date, m.* FROM ( SELECT coalesce(c.maple_monk_id,e.maple_monk_id) AS maple_monk_id_phone, o.* FROM `kerala-ayurveda-wh.maplemonk.KA_Shopify_US_FACT_ITEMS_INTERMEDIATE` o LEFT JOIN ( SELECT email, contact_num as phone, 19700000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT upper(email) email,RIGHT(REGEXP_REPLACE(REPLACE(phone, \' \', \'\'), r\'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num FROM `kerala-ayurveda-wh.maplemonk.KA_Shopify_US_FACT_ITEMS_INTERMEDIATE` where phone is not null ) qualify row_number() over(partition by contact_num order by 1) = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.phone, r\'[^a-zA-Z0-9]+\', \'\'), 10) LEFT JOIN ( SELECT email, contact_num as phone, 19900000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT upper(email) email,RIGHT(REGEXP_REPLACE(REPLACE(phone, \' \', \'\'), r\'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num FROM `kerala-ayurveda-wh.maplemonk.KA_Shopify_US_FACT_ITEMS_INTERMEDIATE` ) qualify row_number() over(partition by email order by 1) = 1 ) e ON upper(e.email) = upper(o.email) ) m LEFT JOIN ( SELECT email, 19800000000 + ROW_NUMBER() OVER (ORDER BY email ASC) AS maple_monk_id FROM ( SELECT DISTINCT upper(email) email FROM `kerala-ayurveda-wh.maplemonk.KA_Shopify_US_FACT_ITEMS_INTERMEDIATE` where phone is null ) a ) d ON upper(d.email) = upper(m.email); ALTER TABLE `kerala-ayurveda-wh.maplemonk.KA_US_Shopify_FACT_ITEMS` ADD COLUMN shopify_new_customer_flag STRING, ADD COLUMN shopify_new_customer_flag_month STRING, ADD COLUMN shopify_acquisition_product STRING, ADD COLUMN shopify_acquisition_channel STRING, ADD COLUMN shopify_acquisition_source STRING; UPDATE `kerala-ayurveda-wh.maplemonk.KA_US_Shopify_FACT_ITEMS` AS A SET A.shopify_new_customer_flag = B.flag FROM ( SELECT DISTINCT order_id, Shopify_customer_id_final, ORDER_TIMESTAMP, CASE WHEN DATE(ORDER_TIMESTAMP) = shopify_first_complete_order_date THEN \'New\' WHEN DATE(ORDER_TIMESTAMP) < shopify_first_complete_order_date OR shopify_first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN DATE(ORDER_TIMESTAMP) > shopify_first_complete_order_date THEN \'Repeat\' END AS flag FROM `kerala-ayurveda-wh.maplemonk.KA_US_Shopify_FACT_ITEMS` ) AS B WHERE A.order_id = B.order_id AND A.Shopify_customer_id_final = B.Shopify_customer_id_final AND DATE(A.ORDER_TIMESTAMP) = DATE(B.ORDER_TIMESTAMP); UPDATE `kerala-ayurveda-wh.maplemonk.KA_US_Shopify_FACT_ITEMS` SET shopify_new_customer_flag = CASE WHEN shopify_new_customer_flag IS NULL AND (CASE WHEN LOWER(order_status) IS NULL THEN TRUE ELSE LOWER(order_status) NOT IN (\'cancelled\') END) THEN \'New\' WHEN shopify_new_customer_flag IS NULL AND (CASE WHEN LOWER(order_status) IS NULL THEN TRUE ELSE LOWER(order_status) IN (\'cancelled\') END) THEN \'Yet to make completed order\' ELSE shopify_new_customer_flag END where true; UPDATE `kerala-ayurveda-wh.maplemonk.KA_US_Shopify_FACT_ITEMS` AS A SET A.shopify_new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, shopify_customer_id_final, DATE(ORDER_TIMESTAMP) AS Order_Date, CASE WHEN LAST_DAY(DATE(ORDER_TIMESTAMP)) = LAST_DAY(DATE(shopify_first_complete_order_date)) THEN \'New\' WHEN LAST_DAY(DATE(ORDER_TIMESTAMP)) < LAST_DAY(DATE(shopify_first_complete_order_date)) OR shopify_acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN LAST_DAY(DATE(ORDER_TIMESTAMP)) > LAST_DAY(DATE(shopify_first_complete_order_date)) THEN \'Repeat\' END AS Flag FROM `kerala-ayurveda-wh.maplemonk.KA_US_Shopify_FACT_ITEMS` ) AS B WHERE A.order_id = B.order_id AND A.shopify_customer_id_final = B.shopify_customer_id_final; UPDATE `kerala-ayurveda-wh.maplemonk.KA_US_Shopify_FACT_ITEMS` SET shopify_new_customer_flag_month = CASE WHEN shopify_new_customer_flag_month IS NULL AND (CASE WHEN LOWER(order_status) IS NULL THEN TRUE ELSE LOWER(order_status) NOT IN (\'cancelled\') END) THEN \'New\' ELSE shopify_new_customer_flag_month END WHERE true; CREATE OR REPLACE TABLE `kerala-ayurveda-wh.maplemonk.US_temp_source_1` AS SELECT shopify_customer_id_final, channel, source FROM ( SELECT DISTINCT shopify_customer_id_final, DATE(order_timestamp) AS order_Date, FINAL_UTM_SOURCE AS SOURCE, FINAL_UTM_CHANNEL AS CHANNEL, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN DATE(order_timestamp) END) OVER (PARTITION BY shopify_customer_id_final) AS firstOrderdate, row_number() over(partition by shopify_customer_id_final order by 1 desc) rw FROM `kerala-ayurveda-wh.maplemonk.KA_US_Shopify_FACT_ITEMS` ) res WHERE order_Date = firstOrderdate and rw = 1; UPDATE `kerala-ayurveda-wh.maplemonk.KA_US_Shopify_FACT_ITEMS` AS a SET a.shopify_acquisition_channel = b.channel FROM `kerala-ayurveda-wh.maplemonk.US_temp_source_1` b WHERE a.shopify_customer_id_final = b.shopify_customer_id_final; UPDATE `kerala-ayurveda-wh.maplemonk.KA_US_Shopify_FACT_ITEMS` AS a SET a.shopify_acquisition_source = b.source FROM `kerala-ayurveda-wh.maplemonk.US_temp_source_1` b WHERE a.shopify_customer_id_final = b.shopify_customer_id_final; CREATE OR REPLACE TABLE `kerala-ayurveda-wh.maplemonk.US_temp_product_1` AS SELECT DISTINCT shopify_customer_id_final, product_name_final, ROW_NUMBER() OVER (PARTITION BY shopify_customer_id_final ORDER BY total_sales DESC) AS rowid FROM ( SELECT DISTINCT shopify_customer_id_final, CAST(order_timestamp AS DATE) AS order_date, product_name_final, total_sales, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN CAST(order_timestamp AS DATE) END) OVER (PARTITION BY shopify_customer_id_final) AS firstOrderdate FROM `kerala-ayurveda-wh.maplemonk.KA_US_Shopify_FACT_ITEMS` ) res WHERE order_date = firstOrderdate; UPDATE kerala-ayurveda-wh.maplemonk.KA_US_Shopify_FACT_ITEMS AS A SET A.shopify_acquisition_product=B.product_name_final FROM ( SELECT * FROM kerala-ayurveda-wh.maplemonk.US_temp_product_1 WHERE rowid=1)B WHERE A.shopify_customer_id_final = B.shopify_customer_id_final; ALTER TABLE `kerala-ayurveda-wh.maplemonk.KA_US_Shopify_FACT_ITEMS` ADD COLUMN SHIPPING_TAX FLOAT64, ADD COLUMN SHIP_PROMOTION_DISCOUNT FLOAT64, ADD COLUMN GIFT_WRAP_PRICE FLOAT64, ADD COLUMN GIFT_WRAP_TAX FLOAT64; Create Or Replace Table `kerala-ayurveda-wh.maplemonk.KA_US_Shopify_FACT_ITEMS_partition_Temporary` as select * from `kerala-ayurveda-wh.maplemonk.KA_US_Shopify_FACT_ITEMS`; drop table `kerala-ayurveda-wh.maplemonk.KA_US_Shopify_FACT_ITEMS`; CREATE TABLE `kerala-ayurveda-wh.maplemonk.KA_US_Shopify_FACT_ITEMS` PARTITION BY order_timestamp AS select * from `kerala-ayurveda-wh.maplemonk.KA_US_Shopify_FACT_ITEMS_partition_Temporary`;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
